package com.citacloud.app.services;
import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.security.MessageDigest; import java.time.LocalDateTime; import java.util.*;
@Service public class ArchivoResultadoEstudioService { private static final long MAXIMO=10L*1024*1024; private static final Set<String> TIPOS=Set.of("application/pdf","image/jpeg","image/png"); private final ArchivoResultadoEstudioRepository archivos; private final DetalleOrdenEstudioRepository detalles; private final OrdenEstudioRepository ordenes; private final Path raiz; public ArchivoResultadoEstudioService(ArchivoResultadoEstudioRepository a,DetalleOrdenEstudioRepository d,OrdenEstudioRepository o,@Value("${citacloud.resultados.storage-dir:storage/resultados}") String r){archivos=a;detalles=d;ordenes=o;raiz=Paths.get(r).toAbsolutePath().normalize();} public ArchivoResultadoEstudio guardar(UUID empresa,UUID detalleId,UUID usuario,MultipartFile archivo){if(archivo==null||archivo.isEmpty())throw new IllegalArgumentException("Seleccione un archivo.");if(archivo.getSize()>MAXIMO)throw new IllegalArgumentException("El archivo supera el máximo de 10 MB.");String tipo=archivo.getContentType();if(!TIPOS.contains(tipo))throw new IllegalArgumentException("Solo se aceptan PDF, JPG, JPEG o PNG.");DetalleOrdenEstudio detalle=detalles.findById(detalleId).orElseThrow(()->new IllegalArgumentException("Estudio no encontrado."));OrdenEstudio orden=ordenes.findById(detalle.getOrdenId()).filter(x->empresa.equals(x.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("No tiene acceso a este estudio."));try{String extension=tipo.equals("application/pdf")?".pdf":tipo.equals("image/png")?".png":".jpg";String clave="tenants/"+empresa+"/patients/"+orden.getPacienteId()+"/results/"+java.time.Year.now()+"/"+UUID.randomUUID()+extension;Path destino=raiz.resolve(clave).normalize();if(!destino.startsWith(raiz))throw new IllegalStateException("Ruta de archivo inválida.");Files.createDirectories(destino.getParent());try(InputStream in=archivo.getInputStream()){Files.copy(in,destino,StandardCopyOption.REPLACE_EXISTING);}ArchivoResultadoEstudio a=new ArchivoResultadoEstudio();a.setEmpresaId(empresa);a.setPacienteId(orden.getPacienteId());a.setOrdenId(orden.getId());a.setDetalleOrdenId(detalleId);a.setStorageKey(clave);a.setNombreOriginal(archivo.getOriginalFilename());a.setMimeType(tipo);a.setTamanioBytes(archivo.getSize());a.setChecksum(hash(destino));a.setSubidoPor(usuario);a.setCreadoEn(LocalDateTime.now());return archivos.save(a);}catch(IOException e){throw new IllegalStateException("No se pudo almacenar el archivo del resultado.",e);}} public ArchivoResultadoEstudio guardar(UUID empresa,UUID detalleId,UUID usuario,String nombre,String tipo,byte[] contenido){if(contenido==null||contenido.length==0)throw new IllegalArgumentException("Seleccione un archivo.");if(contenido.length>MAXIMO)throw new IllegalArgumentException("El archivo supera el máximo de 10 MB.");if(!TIPOS.contains(tipo))throw new IllegalArgumentException("Solo se aceptan PDF, JPG, JPEG o PNG.");DetalleOrdenEstudio detalle=detalles.findById(detalleId).orElseThrow(()->new IllegalArgumentException("Estudio no encontrado."));OrdenEstudio orden=ordenes.findById(detalle.getOrdenId()).filter(x->empresa.equals(x.getEmpresaId())).orElseThrow(()->new IllegalArgumentException("No tiene acceso a este estudio."));try{String extension=tipo.equals("application/pdf")?".pdf":tipo.equals("image/png")?".png":".jpg";String clave="tenants/"+empresa+"/patients/"+orden.getPacienteId()+"/results/"+java.time.Year.now()+"/"+UUID.randomUUID()+extension;Path destino=raiz.resolve(clave).normalize();if(!destino.startsWith(raiz))throw new IllegalStateException("Ruta de archivo inválida.");Files.createDirectories(destino.getParent());Files.write(destino,contenido,StandardOpenOption.CREATE_NEW);ArchivoResultadoEstudio a=new ArchivoResultadoEstudio();a.setEmpresaId(empresa);a.setPacienteId(orden.getPacienteId());a.setOrdenId(orden.getId());a.setDetalleOrdenId(detalleId);a.setStorageKey(clave);a.setNombreOriginal(nombre);a.setMimeType(tipo);a.setTamanioBytes(contenido.length);a.setChecksum(hash(destino));a.setSubidoPor(usuario);a.setCreadoEn(LocalDateTime.now());return archivos.save(a);}catch(IOException e){throw new IllegalStateException("No se pudo almacenar el archivo del resultado.",e);}} public List<ArchivoResultadoEstudio> listar(UUID empresa,UUID detalle){return archivos.findByEmpresaIdAndDetalleOrdenId(empresa,detalle);} public ArchivoResultadoEstudio buscar(UUID empresa,UUID id){return archivos.findByIdAndEmpresaId(id,empresa).orElseThrow(()->new IllegalArgumentException("Archivo no encontrado."));} public byte[] contenido(UUID empresa,UUID id){try{return Files.readAllBytes(raiz.resolve(buscar(empresa,id).getStorageKey()).normalize());}catch(IOException e){throw new IllegalStateException("No se pudo leer el archivo.",e);}} private String hash(Path archivo)throws IOException{try(InputStream in=Files.newInputStream(archivo)){MessageDigest d=MessageDigest.getInstance("SHA-256");return HexFormat.of().formatHex(d.digest(in.readAllBytes()));}catch(Exception e){throw new IOException(e);}} }
